package main

import (
	"encoding/gob"
	"bytes"
	"fmt"
	"net/http"
	"os/exec"
	"github.com/gin-gonic/gin"
	"encoding/base64"
)

// Task represents a serialized job submitted by authenticated clients
type Task struct {
	Name    string
	Command string
	Args    []string
}

// CommandResult wraps execution output
type CommandResult struct {
	Output string `json:"output"`
	Error  string `json:"error,omitempty"`
}

func init() {
	gob.Register(Task{})
}

// executeTask deserializes and runs a task payload
func executeTask(payload []byte) (*CommandResult, error) {
	buf := bytes.NewBuffer(payload)
	dec := gob.NewDecoder(buf)

	var task Task
	if err := dec.Decode(&task); err != nil {
		return nil, fmt.Errorf("decode error: %w", err)
	}

	// Execute the task command
	cmd := exec.Command(task.Command, task.Args...)
	output, err := cmd.CombinedOutput()
	if err != nil {
		return &CommandResult{
			Output: string(output),
			Error:  err.Error(),
		}, nil
	}

	return &CommandResult{Output: string(output)}, nil
}

func main() {
	r := gin.Default()

	// Health check endpoint
	r.GET("/health", func(c *gin.Context) {
		c.JSON(http.StatusOK, gin.H{"status": "ok"})
	})

	// Task submission endpoint - accepts base64-encoded gob payloads
	// Only reachable via CloudFront signed URLs in production
	r.POST("/api/v1/tasks/execute", func(c *gin.Context) {
		encodedPayload := c.PostForm("payload")
		if encodedPayload == "" {
			c.JSON(http.StatusBadRequest, gin.H{"error": "missing payload"})
			return
		}

		payload, err := base64.StdEncoding.DecodeString(encodedPayload)
		if err != nil {
			c.JSON(http.StatusBadRequest, gin.H{"error": "invalid base64"})
			return
		}

		// Size limit check
		if len(payload) > 4096 {
			c.JSON(http.StatusRequestEntityTooLarge, gin.H{"error": "payload too large"})
			return
		}

		result, err := executeTask(payload)
		if err != nil {
			c.JSON(http.StatusInternalServerError, gin.H{"error": err.Error()})
			return
		}

		c.JSON(http.StatusOK, result)
	})

	// Internal metrics (not exposed via CloudFront)
	r.GET("/internal/metrics", func(c *gin.Context) {
		c.JSON(http.StatusOK, gin.H{"requests": 0})
	})

	r.Run(":8080")
}
